function getAttribute(node, name) {
  return node.attrs?.find((attribute) => attribute.name === name)?.value;
}

function setAttribute(node, name, value) {
  node.attrs = node.attrs || [];
  const existing = node.attrs.find((attribute) => attribute.name === name);
  if (existing) {
    existing.value = value;
  } else {
    node.attrs.push({ name, value });
  }
}

function removeAttribute(node, name) {
  if (!node.attrs) return;
  node.attrs = node.attrs.filter((attribute) => attribute.name !== name);
}

function visit(node, visitor) {
  visitor(node);
  for (const child of node.childNodes || []) {
    visit(child, visitor);
  }
}

function findAll(document, predicate) {
  const matches = [];
  visit(document, (node) => {
    if (predicate(node)) matches.push(node);
  });
  return matches;
}

function findOne(document, predicate, description) {
  const matches = findAll(document, predicate);
  assert.equal(matches.length, 1, `Expected one ${description}`);
  return matches[0];
}

function replaceText(node, value) {
  node.childNodes = [{
    nodeName: "#text",
    value,
    parentNode: node
  }];
}

function setMeta(document, selector, value) {
  const [attribute, expected] = selector;
  const node = findOne(
    document,
    (candidate) =>
      candidate.tagName === "meta" &&
      getAttribute(candidate, attribute) === expected,
    `meta ${attribute}="${expected}"`
  );
  setAttribute(node, "content", value);
}

function setLink(document, rel, hreflang, href) {
  const node = findOne(
    document,
    (candidate) =>
      candidate.tagName === "link" &&
      getAttribute(candidate, "rel") === rel &&
      (hreflang === undefined ||
        getAttribute(candidate, "hreflang") === hreflang),
    hreflang ? `${rel} ${hreflang} link` : `${rel} link`
  );
  setAttribute(node, "href", href);
}

function absoluteUrl(publicPath) {
  return new URL(publicPath, `${baseUrl}/`).href;
}

function localizePublicUrl(value, parentType, key) {
  let url;
  try {
    url = new URL(value);
  } catch {
    return value;
  }
  if (url.origin !== new URL(baseUrl).origin) return value;
  if (
    parentType === "Organization" ||
    (parentType === "SoftwareApplication" &&
      (key === "@id" || key === "url"))
  ) {
    return value;
  }
  if (
    url.pathname === "/" &&
    (url.hash === "#organization" || url.hash === "#software")
  ) {
    return value;
  }
  const route = routeByEnglishPath.get(url.pathname);
  if (!route) return value;
  return `${absoluteUrl(route.chinesePath)}${url.hash}`;
}

function translateStructuredValue(value, key, parentType) {
  if (key === "inLanguage") return "zh-CN";
  if (Array.isArray(value)) {
    return value.map((entry) =>
      translateStructuredValue(entry, key, parentType)
    );
  }
  if (value && typeof value === "object") {
    const type = value["@type"] || parentType;
    return Object.fromEntries(
      Object.entries(value).map(([childKey, childValue]) => [
        childKey,
        translateStructuredValue(childValue, childKey, type)
      ])
    );
  }
  if (typeof value !== "string") return value;
  if (/^https?:\/\//.test(value)) {
    return localizePublicUrl(value, parentType, key);
  }
  if (structuredTranslations.has(value)) {
    return structuredTranslations.get(value);
  }
  const needsTranslation =
    key === "description" ||
    key === "alternateName" ||
    key === "applicationSubCategory" ||
    key === "text" ||
    key === "featureList" ||
    (key === "name" && parentType !== "Organization" &&
      parentType !== "SoftwareApplication" && parentType !== "WebSite");
  assert.ok(!needsTranslation, `Missing JSON-LD translation for "${value}"`);
  return value;
}

function localizeReference(value, route) {
  if (!value || value.startsWith("#") || value.startsWith("data:")) {
    return value;
  }
  let url;
  try {
    url = new URL(value, absoluteUrl(route.englishPath));
  } catch {
    return value;
  }
  if (url.origin !== new URL(baseUrl).origin) return value;
  const targetRoute = routeByEnglishPath.get(url.pathname);
  if (targetRoute) {
    return `${targetRoute.chinesePath}${url.search}${url.hash}`;
  }
  return `${url.pathname}${url.search}${url.hash}`;
}

function localizeSrcset(value, route) {
  return value.split(",").map((candidate) => {
    const match = candidate.trim().match(/^(\S+)([\s\S]*)$/);
    if (!match) return candidate;
    return `${localizeReference(match[1], route)}${match[2]}`;
  }).join(", ");
}

function localizeDocument(route) {
  const sourcePath = path.join(websiteDir, route.source);
  const document = parse5.parse(fs.readFileSync(sourcePath, "utf8"));
  const html = findOne(
    document,
    (node) => node.tagName === "html",
    "html element"
  );
  setAttribute(html, "lang", "zh-CN");

  visit(document, (node) => {
    if (!node.attrs) return;
    const chineseText = getAttribute(node, "data-zh");
    if (chineseText !== undefined) {
      replaceText(node, chineseText);
    }
    const chineseAria = getAttribute(node, "data-zh-aria");
    if (chineseAria !== undefined) {
      setAttribute(node, "aria-label", chineseAria);
    }
    const chineseAlt = getAttribute(node, "data-zh-alt");
    if (chineseAlt !== undefined) {
      setAttribute(node, "alt", chineseAlt);
    }
    for (const name of ["href", "src"]) {
      const reference = getAttribute(node, name);
      if (reference !== undefined) {
        setAttribute(node, name, localizeReference(reference, route));
      }
    }
    const srcset = getAttribute(node, "srcset");
    if (srcset !== undefined) {
      setAttribute(node, "srcset", localizeSrcset(srcset, route));
    }
    for (const name of ["data-zh", "data-zh-aria", "data-zh-alt"]) {
      removeAttribute(node, name);
    }
  });

  const title = findOne(
    document,
    (node) => node.tagName === "title",
    "title"
  );
  replaceText(title, route.metadata.title);
  setMeta(document, ["name", "description"], route.metadata.description);
  setMeta(document, ["property", "og:title"], route.metadata.ogTitle);
  setMeta(
    document,
    ["property", "og:description"],
    route.metadata.ogDescription
  );
  setMeta(document, ["property", "og:url"], absoluteUrl(route.chinesePath));
  setMeta(document, ["property", "og:locale"], "zh_CN");
  setMeta(document, ["property", "og:locale:alternate"], "en_US");

  const optionalMetadata = [
    ["name", "twitter:title", route.metadata.ogTitle],
    ["name", "twitter:description", route.metadata.ogDescription],
    ["property", "og:image:alt", route.metadata.imageAlt],
    ["name", "twitter:image:alt", route.metadata.imageAlt]
  ];
  for (const [attribute, expected, value] of optionalMetadata) {
    const matches = findAll(
      document,
      (node) =>
        node.tagName === "meta" &&
        getAttribute(node, attribute) === expected
    );
    if (matches.length > 0) {
      assert.ok(value, `${route.source} needs Chinese ${expected}`);
      assert.equal(matches.length, 1);
      setAttribute(matches[0], "content", value);
    }
  }

  setLink(document, "canonical", undefined, absoluteUrl(route.chinesePath));
  setLink(document, "alternate", "en", absoluteUrl(route.englishPath));
  setLink(
    document,
    "alternate",
    "zh-Hans",
    absoluteUrl(route.chinesePath)
  );
  setLink(document, "alternate", "x-default", absoluteUrl(route.englishPath));

  const languageLink = findOne(
    document,
    (node) => getAttribute(node, "data-language-link") !== undefined,
    "language link"
  );
  setAttribute(languageLink, "href", route.englishPath);
  setAttribute(languageLink, "lang", "en");
  setAttribute(languageLink, "hreflang", "en");
  setAttribute(languageLink, "aria-label", "切换到英文");
  replaceText(languageLink, "EN");
  removeAttribute(languageLink, "data-language-link");

  const structuredData = findAll(
    document,
    (node) =>
      node.tagName === "script" &&
      getAttribute(node, "type") === "application/ld+json"
  );
  assert.ok(structuredData.length > 0, `${route.source} needs JSON-LD`);
  for (const script of structuredData) {
    const source = script.childNodes
      .filter((node) => node.nodeName === "#text")
      .map((node) => node.value)
      .join("");
    const translated = translateStructuredValue(
      JSON.parse(source),
      undefined,
      undefined
    );
    replaceText(script, `\n    ${JSON.stringify(translated, null, 2)
      .replace(/\n/g, "\n    ")}\n  `);
  }

  assert.equal(
    findAll(
      document,
      (node) =>
        node.tagName === "script" &&
        /(?:^|\/)i18n\.js(?:\?|$)/.test(getAttribute(node, "src") || "")
    ).length,
    0,
    `${route.source} still loads i18n.js`
  );

  const serialized = parse5.serialize(document);
  return `${serialized.replace(
    "<!DOCTYPE html>",
    `<!DOCTYPE html>\n${generatedNotice}`
  )}\n`;
}

function sitemapEntry(route, publicPath) {
  const englishUrl = absoluteUrl(route.englishPath);
  const chineseUrl = absoluteUrl(route.chinesePath);
  return [
    "  <url>",
    `    <loc>${absoluteUrl(publicPath)}</loc>`,
    `    <xhtml:link rel="alternate" hreflang="en" href="${englishUrl}"/>`,
    `    <xhtml:link rel="alternate" hreflang="zh-Hans" href="${chineseUrl}"/>`,
    `    <xhtml:link rel="alternate" hreflang="x-default" href="${englishUrl}"/>`,
    `    <lastmod>${route.lastmod}</lastmod>`,
    "  </url>"
  ].join("\n");
}

function generateSitemap() {
  const entries = routes.flatMap((route) => [
    sitemapEntry(route, route.englishPath),
    sitemapEntry(route, route.chinesePath)
  ]);
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"',
    '  xmlns:xhtml="http://www.w3.org/1999/xhtml">',
    ...entries,
    "</urlset>",
    ""
  ].join("\n");
}

function generatedArtifacts() {
  const artifacts = new Map();
  for (const route of routes) {
    const relative = route.chinesePath === "/zh/"
      ? "zh/index.html"
      : `${route.chinesePath.replace(/^\/+/, "")}.html`;
    artifacts.set(relative, localizeDocument(route));
  }
  artifacts.set("sitemap.xml", generateSitemap());
  return artifacts;
}

function listHtmlFiles(directory) {
  if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory, { withFileTypes: true })
    .flatMap((entry) => {
      const entryPath = path.join(directory, entry.name);
      if (entry.isDirectory()) return listHtmlFiles(entryPath);
      return entry.name.endsWith(".html") ? [entryPath] : [];
    });
}

function checkArtifacts(artifacts) {
  const expectedChineseFiles = new Set(
    [...artifacts.keys()].filter((file) => file.startsWith("zh/"))
  );
  const chineseDir = path.join(websiteDir, "zh");
  const actualChineseFiles = listHtmlFiles(chineseDir)
    .map((file) =>
      path.relative(websiteDir, file).split(path.sep).join("/")
    );
  assert.deepEqual(
    new Set(actualChineseFiles),
    expectedChineseFiles,
    "Generated Chinese page set is stale"
  );
  for (const [relative, expected] of artifacts) {
    const file = path.join(websiteDir, relative);
    assert.ok(fs.existsSync(file), `${relative} has not been generated`);
    assert.equal(
      fs.readFileSync(file, "utf8"),
      expected,
      `${relative} is stale; run npm run generate:website-locales`
    );
  }
}

function writeArtifacts(artifacts) {
  const chineseDir = path.join(websiteDir, "zh");
  fs.rmSync(chineseDir, { recursive: true, force: true });
  for (const [relative, contents] of artifacts) {
    const file = path.join(websiteDir, relative);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, contents);
  }
}

function main() {
  const artifacts = generatedArtifacts();
  if (process.argv.includes("--check")) {
    checkArtifacts(artifacts);
    process.stdout.write(
      `Verified ${routes.length} generated Chinese pages and the bilingual sitemap.\n`
    );
    return;
  }
  writeArtifacts(artifacts);
  process.stdout.write(
    `Generated ${routes.length} Chinese pages and the bilingual sitemap.\n`
  );
}

if (require.main === module) {
  try {
    main();
  } catch (error) {
    console.error(error);
    process.exitCode = 1;
  }
}

module.exports = {
  baseUrl,
  generatedArtifacts,
  routes
};
